1	// Soporte exclusivo de las pruebas de spec-0. Complementa factory/regresion/helpers.ts (que este spec no puede editar).
2	// Selectores tomados del código de Moodle 5.3 en entorno/.moodle-src/. Las aserciones que deciden si un criterio se
3	// cumple están en los .spec.ts; acá solo hay esperas y comprobaciones de que cada paso auxiliar terminó bien.
4	import { expect, type Locator, type Page } from '@playwright/test';
5	import { bloquePregunta } from '../../../factory/regresion/helpers';
6	
7	export type TipoPregunta = 'multichoice' | 'truefalse' | 'essay';
8	export type Categoria = { id: string; contexto: string };
9	
10	type ConfigMoodle = { courseId: number; contextid: number; sesskey: string };
11	
12	const configMoodle = (page: Page): Promise<ConfigMoodle> =>
13	  page.evaluate(() => (window as unknown as { M: { cfg: ConfigMoodle } }).M.cfg);
14	
15	/** Nombre único que no contiene "Examen de regresión", para que abrirQuiz nunca tome este examen por QUIZ-REG. */
16	export const nombreUnico = (prefijo: string, proyecto: string) => `${prefijo} ${proyecto} ${Date.now()}`;
17	
18	/**
19	 * TinyMCE crea su iframe oculto y lo muestra al terminar de cargar sus módulos, lo que puede superar los 5 s por defecto
20	 * de expect con el servidor bajo carga. Es una espera de carga: la aserción sobre el editor no cambia.
21	 */
22	export const ESPERA_EDITOR = 30_000;
23	
24	/**
25	 * Espera a que terminen de inicializarse los módulos AMD de la página (misma señal que usa Behat y enviarIntento() de
26	 * helpers.ts). Sustituye a 'networkidle', que en Moodle nunca se cumple por sus peticiones periódicas.
27	 */
28	export async function esperarModulos(page: Page) {
29	  await page.waitForLoadState('load');
30	  await page.waitForFunction(() => (window as unknown as { M?: { util?: { pending_js?: unknown[] } } }).M?.util?.pending_js?.length === 0);
31	}
32	
33	export async function idCursoQA101(page: Page): Promise<number> {
34	  await page.goto('/course/view.php?name=QA101');
35	  return (await configMoodle(page)).courseId;
36	}
37	
38	// ---------------------------------------------------------------------------------------------------------
39	// Examen
40	
41	export async function abrirFormularioExamen(page: Page, curso: number) {
42	  await page.goto(`/course/modedit.php?add=quiz&course=${curso}&section=0`);
43	  await expect(page.locator('#id_introeditor_ifr')).toBeVisible({ timeout: ESPERA_EDITOR });
44	}
45	
46	/**
47	 * Deja abierto el índice del curso (solo escritorio) para capturar siempre el mismo estado. Abierto o cerrado es una
48	 * preferencia guardada por usuario (drawer-open-index, boost/layout/drawers.php:34) que sobrevive entre corridas: no es
49	 * parte de la pantalla que se protege. En móvil no aplica: drawers.js:328 lo cierra al cargar sin mirar la preferencia.
50	 */
51	export async function abrirIndiceCurso(page: Page) {
52	  const abrir = page.getByRole('button', { name: 'Abrir índice del curso' });
53	  if (await abrir.isVisible()) await abrir.click();
54	  // El cajón abierto lleva la clase "show" (drawers.mustache:66); no depende del idioma del botón.
55	  await expect(page.locator('#theme_boost-drawers-courseindex')).toHaveClass(/\bshow\b/);
56	}
57	
58	/** Guarda con "Guardar cambios y mostrar" (#id_submitbutton) y devuelve el cmid del examen creado o editado. */
59	export async function guardarExamen(page: Page): Promise<number> {
60	  await page.locator('#id_submitbutton').click();
61	  await expect(page).toHaveURL(/mod\/quiz\/view\.php\?id=\d+/);
62	  return Number(new URL(page.url()).searchParams.get('id'));
63	}
64	
65	export async function crearExamen(page: Page, curso: number, nombre: string): Promise<number> {
66	  await abrirFormularioExamen(page, curso);
67	  await page.locator('#id_name').fill(nombre);
68	  return guardarExamen(page);
69	}
70	
71	export async function eliminarExamen(page: Page, cmid: number) {
72	  const { sesskey } = await configMoodle(page);
73	  await page.goto(`/course/mod.php?delete=${cmid}&sesskey=${sesskey}`);
74	  await page.getByRole('button', { name: 'Sí', exact: true }).click();
75	  await expect(page).toHaveURL(/course\/(view|section)\.php/);
76	}
77	
78	// ---------------------------------------------------------------------------------------------------------
79	// Banco de preguntas
80	
81	/** cmid del banco compartido de QA101, leído de la lista de bancos del curso. */
82	export async function cmidBanco(page: Page, curso: number): Promise<number> {
83	  await page.goto(`/question/banks.php?courseid=${curso}`);
84	  const banco = page.locator('.shared-banks .questioncount[data-cmid]').first();
85	  await expect(banco).toBeAttached();
86	  return Number(await banco.getAttribute('data-cmid'));
87	}
88	
89	export const urlCategorias = (banco: number) => `/question/bank/managecategories/category.php?cmid=${banco}`;
90	const urlBanco = (banco: number, c: Categoria) => `/question/edit.php?cmid=${banco}&cat=${c.id},${c.contexto}`;
91	
92	export const filaCategoria = (page: Page, nombre: string): Locator =>
93	  page.locator(`li.qbank_managecategories-item[data-categoryname=${JSON.stringify(nombre)}]`);
94	
95	export const filaPregunta = (page: Page, nombre: string): Locator =>
96	  page.locator('#categoryquestions tbody tr', { hasText: nombre });
97	
98	/**
99	 * Crea una categoría propia en el banco. Es necesaria porque el banco sembrado no tiene categoría por defecto
100	 * (question_bank_helper.php:660 usa skipdefaultcategory): sin esto, las preguntas caerían en Álgebra.
101	 */
102	export async function crearCategoria(page: Page, banco: number, nombre: string): Promise<Categoria> {
103	  await page.goto(urlCategorias(banco));
104	  // El botón recibe su evento cuando el componente reactivo termina de cargar el estado.
105	  await esperarModulos(page);
106	  await page.locator('#qbank_managecategories-addcategory [data-action="addeditcategory"]').click();
107	  const modal = page.locator('[data-region="modal"]').filter({ has: page.locator('input[name="name"]') });
108	  await modal.locator('input[name="name"]').fill(nombre);
109	  await modal.locator('[data-action="save"]').click();
110	  await expect(filaCategoria(page, nombre)).toHaveCount(1);
111	  await page.reload();
112	  const id = await filaCategoria(page, nombre).getAttribute('data-categoryid');
113	  const { contextid } = await configMoodle(page);
114	  return { id: String(id), contexto: String(contextid) };
115	}
116	
117	/** Escribe en un editor TinyMCE. `iframe` es el selector CSS de su iframe. */
118	export async function escribirEditor(page: Page, iframe: string, texto: string) {
119	  await expect(page.locator(iframe)).toBeVisible({ timeout: ESPERA_EDITOR });
120	  // El iframe ya es visible mientras TinyMCE sigue cargando: su "throbber" (aria-busy) tapa el editor e intercepta el
121	  // click. Se espera a que desaparezca antes de interactuar.
122	  await expect(page.locator('.tox-tinymce', { has: page.locator(iframe) }).locator('.tox-throbber')).toBeHidden({
123	    timeout: ESPERA_EDITOR,
124	  });
125	  const cuerpo = page.frameLocator(iframe).locator('body');
126	  await cuerpo.click();
127	  await cuerpo.fill(texto);
128	}
129	
130	/** Crea una pregunta desde el botón "Crear una nueva pregunta..." del banco, dentro de la categoría indicada. */
131	export async function crearPregunta(page: Page, banco: number, categoria: Categoria, tipo: TipoPregunta, nombre: string) {
132	  await page.goto(urlBanco(banco, categoria));
133	  // edit.php:73 corta la página sin pintar el banco mientras la migración de mod_qbank siga en la cola de tareas ad hoc.
134	  await expect(
135	    page.getByRole('alert').filter({ hasText: 'transfer_question_categories' }),
136	    'Entorno: las tareas ad hoc de mod_qbank no terminaron; revisar el cron o ejecutarlas antes de esta prueba',
137	  ).toHaveCount(0);
138	  // Con teclado, no con click: en móvil, el punto de click de Playwright cae sobre elementos que están ANTES del botón
139	  // en el flujo (h2, filtros) o bajo la barra fija, aunque nada lo tape en el DOM. El teclado no depende de coordenadas
140	  // y recorre el mismo botón, el mismo diálogo y el mismo envío. El botón nace deshabilitado hasta que carga chooser.js
141	  // y el diálogo solo habilita "Add" al elegir un tipo: se espera cada estado porque press() no lo hace.
142	  const crear = page.getByRole('button', { name: /crear una nueva pregunta/i });
143	  await expect(crear).toBeEnabled();
144	  await crear.press('Enter');
145	  const tipoPregunta = page.locator(`#item_qtype_${tipo}`);
146	  await expect(tipoPregunta).toBeVisible();
147	  await tipoPregunta.press('Space');
148	  await expect(tipoPregunta).toBeChecked();
149	  const agregar = page.locator('#chooserform input.submitbutton');
150	  await expect(agregar).toBeEnabled();
151	  await agregar.press('Enter');
152	  await expect(page).toHaveURL(/question\/bank\/editquestion\/question\.php/);
153	
154	  await page.locator('#id_name').fill(nombre);
155	  await escribirEditor(page, '#id_questiontext_ifr', `Enunciado de ${nombre}`);
156	  if (tipo === 'multichoice') {
157	    await escribirEditor(page, '#id_answer_0_ifr', 'Correcta');
158	    await page.locator('#id_fraction_0').selectOption('1.0'); // 100%
159	    await escribirEditor(page, '#id_answer_1_ifr', 'Incorrecta');
160	  } else if (tipo === 'truefalse') {
161	    await page.locator('#id_correctanswer').selectOption('1'); // 1 = Verdadero
162	  }
163	  await page.locator('#id_submitbutton').click();
164	  await expect(page).toHaveURL(/question\/edit\.php/);
165	  await expect(filaPregunta(page, nombre)).toHaveCount(1);
166	}
167	
168	/** Add > from question bank > Switch bank > filtro de categoría > Add selected questions to the quiz. */
169	export async function agregarDesdeBanco(page: Page, examen: number, banco: number, categoria: string, preguntas: string[]) {
170	  await page.goto(`/mod/quiz/edit.php?cmid=${examen}`);
171	  await esperarModulos(page);
172	  await page.locator('.last-add-menu a[data-bs-toggle="dropdown"]').click();
173	  await page.locator('.last-add-menu [data-action="questionbank"]').click();
174	
175	  // El modal abre en el banco privado del examen; las preguntas están en el banco del curso.
176	  await page.locator('#switch-question-bank').click();
177	  // bank_switcher.js oculta esta selección justo antes de registrar el clic de los enlaces.
178	  await expect(page.locator('.search-banks .form-autocomplete-selection.d-none')).toHaveCount(1);
179	  // Tras visitarlo, el banco también aparece en "recientes" con el mismo data-newmodid; "banks in course" siempre lo lista.
180	  await page.locator(`.course-shared-banks a[data-newmodid="${banco}"]`).click();
181	
182	  // filter.js se inicia de forma asíncrona (espera cadenas de idioma) y al terminar carga la categoría por defecto, lo que
183	  // pisa un filtro aplicado antes. La primera tabla (categoría por defecto, con preguntas sembradas) marca que ya terminó.
184	  await expect(page.locator('#categoryquestions tbody tr').first()).toBeVisible({ timeout: ESPERA_EDITOR });
185	  await esperarModulos(page);
186	
187	  const filtro = page.locator('[data-filter-type="category"]');
188	  const entrada = filtro.locator('div.form-autocomplete-input input');
189	  // Elegir la sugerencia puede no registrarse (en móvil la lista se cierra por blur antes del click). Si el filtro queda
190	  // sin la categoría, "Apply" falla la validación en silencio (datafilter.js:438) y la tabla no cambia. Se confirma que la
191	  // categoría quedó seleccionada antes de aplicar y se repite la selección hasta que sea así.
192	  await expect(async () => {
193	    await entrada.click();
194	    await entrada.fill(categoria);
195	    await filtro.locator('.form-autocomplete-suggestions li', { hasText: categoria }).click({ timeout: 5_000 });
196	    await expect(filtro.locator('.form-autocomplete-selection'), 'La categoría no quedó seleccionada en el filtro').toContainText(
197	      categoria,
198	      { timeout: 3_000 },
199	    );
200	  }).toPass({ timeout: ESPERA_EDITOR });
201	  await page.locator('[data-filteraction="apply"]').click();
202	
203	  // La tabla se vacía y se recarga por fragmento: se espera a que aparezca la pregunta de la categoría filtrada.
