    closeDrawer({focusOnOpenButton = true, updatePreferences = true} = {}) {

    const pendingPromise = new Pending('theme_boost/drawers:close');

    const hideEvent = this.dispatchEvent(Drawers.eventTypes.drawerHide, true);
